var smsDigits = String(Context.getVariable("phone_number") || "").replace(/\D/g, "");
Context.setVariable("SMS_Number", "+" + smsDigits);
Context.setVariable("SMS_Message", String(Context.getVariable("sms_message") || ""));
// "true" for +1 numbers (US/Canada) -> US sender; anything else -> UK sender
Context.setVariable("wf_sms_from_us_number", (smsDigits.length === 11 && smsDigits.charAt(0) === "1") ? "true" : "false");

var MAX_ATTEMPTS = 3;
var wf_entered_pin = String(Context.getVariable("entered_pin") || "").replace(/\D/g, "");
var wf_sent_pin = String(Context.getVariable("sent_pin") || "").replace(/\D/g, "");
var wf_pending_profile_id = String(Context.getVariable("pending_profile_id") || "");
var wf_attempts = parseInt(String(Context.getVariable("otp_attempts") || "0"), 10) || 0;

if (wf_attempts >= MAX_ATTEMPTS) {
    // Already locked out: never authenticate, even with the right code.
    Context.setVariable("wf_otp_result", "LOCKED");
    Context.setVariable("wf_authenticated", "false");
    Context.setVariable("wf_profile_id", "");
} else if (wf_sent_pin.length === 6 && wf_entered_pin === wf_sent_pin && wf_pending_profile_id !== "") {
    Context.setVariable("wf_otp_result", "MATCH");
    Context.setVariable("wf_authenticated", "true");
    Context.setVariable("wf_profile_id", wf_pending_profile_id);
} else {
    wf_attempts = wf_attempts + 1;
    Context.setVariable("wf_otp_result", wf_attempts >= MAX_ATTEMPTS ? "LOCKED" : "NO_MATCH");
    Context.setVariable("wf_authenticated", "false");
    Context.setVariable("wf_profile_id", "");
}
Context.setVariable("wf_otp_attempts", String(wf_attempts));

var wf_result = String(Context.getVariable("wf_otp_result") || "");
var wf_next;
if (wf_result === "MATCH") {
    wf_next = "Verified. Do not call verify_otp again. Your next action is execute_sql to log auth_success, then reply_to_coordinator with exactly: STATUS: AUTHENTICATED";
} else if (wf_result === "LOCKED") {
    wf_next = "Locked out. Do not call verify_otp or send_one_time_pin again. Your next action is execute_sql to log the lockout, then reply_to_coordinator with exactly: STATUS: AUTH_FAILED | REASON: max_attempts";
} else if (wf_attempts <= 1) {
    wf_next = "Wrong code. Do not call verify_otp again in this turn. Your next action is reply_to_coordinator with exactly: STATUS: NEED_INPUT | ASK_CUSTOMER: \"That code didn't match. What is the six-digit code you received? If you'd like, I can send you a new one.\"";
} else {
    wf_next = "Wrong code again. Do not call verify_otp again in this turn. Your next action is reply_to_coordinator with exactly: STATUS: NEED_INPUT | ASK_CUSTOMER: \"That code still didn't match, and you have one try left. Please check the text message and enter the six-digit code, or I can send you a new one.\"";
}
Context.setVariable("wf_otp_next_step", wf_next);

// random number between 100000 and 999999 to avoid leading zeros
let oneTimePin = String(Math.floor(Math.random() * 900000) + 100000);

Context.setVariable('One_Time_Pin', oneTimePin);

var smsDigits = String(Context.getVariable("phone_number") || "").replace(/\D/g, "");
Context.setVariable('SMS_Number', '+' + smsDigits);

Context.setVariable('SMS_Message',
    'Your one-time authentication PIN is ' + oneTimePin);

Context.setVariable("wf_pending_profile_id", String(Context.getVariable("pending_profile_id") || ""));

// Guest details for the other agents (only verify_otp unlocks them via authenticated)
Context.setVariable("wf_name_given", String(Context.getVariable("name_given") || ""));
Context.setVariable("wf_name_surname", String(Context.getVariable("name_surname") || ""));
Context.setVariable("wf_email", String(Context.getVariable("email") || ""));
Context.setVariable("wf_is_member", String(Context.getVariable("is_member") || ""));
Context.setVariable("wf_in_house", String(Context.getVariable("in_house") || ""));
Context.setVariable("wf_in_house_room", String(Context.getVariable("in_house_room") || ""));
Context.setVariable("wf_upcoming_arrival_date", String(Context.getVariable("upcoming_arrival_date") || ""));
Context.setVariable("wf_phone_number", String(Context.getVariable("phone_number") || ""));

// "true" for +1 numbers (US/Canada) -> US sender; anything else -> UK sender
Context.setVariable("wf_sms_from_us_number", (smsDigits.length === 11 && smsDigits.charAt(0) === "1") ? "true" : "false");
Context.setVariable("wf_otp_next_step", "Code sent. Your next action is reply_to_coordinator with exactly: STATUS: NEED_INPUT | ASK_CUSTOMER: \"I've sent a six-digit code to your mobile. Please say or enter it when it arrives.\"");

